    "sourcePages": "562–563",
    "question": "How does Wilson describe Leon Sullivan’s 10-36 plan and its economic outcomes?",
    "answer": "Wilson explains Sullivan’s 10-36 plan had members contribute $10 monthly for 36 months to pooled investment and charitable arms that funded Progress Investments Associates, which built Progress Plaza and other businesses, demonstrating a church-led economic development model."
