    "sourcePages": "657",
    "question": "What point does the chapter make about oppression being renamed in the context of U.S. race relations?",
    "answer": "The chapter contends that oppression can be made invisible by renaming it freedom and democracy, so dominated groups feel free even while being exploited and voluntarily enrich those who dominate them."
